INSERT INTO movies (title, type, year, duration, age_rating, star_rating, vote_count, poster_url, backdrop_url, trailer_url, genres, language, category, weekend_gross, total_gross, description) VALUES
('The Batman – Part II', 'Movie', 2026, '2h 45m', 'PG-13', 8.4, '124K', 'https://picsum.photos/seed/batman2/300/450', 'https://picsum.photos/seed/batman2-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Crime', 'Drama'], 'English', 'in-theaters', '$185M', '$185M', 'Robert Pattinson returns as the Dark Knight in Matt Reeves'' noir-soaked sequel. Gotham faces a new threat rising from the ashes of the flooded city.'),
('Shrek 5', 'Movie', 2026, '1h 35m', 'PG', 7.8, '89K', 'https://picsum.photos/seed/shrek5/300/450', 'https://picsum.photos/seed/shrek5-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Animation', 'Comedy', 'Family'], 'English', 'in-theaters', '$62M', '$680M', 'The ogre is back after 16 years! Shrek and Fiona navigate parenthood while a new fairy tale villain threatens Far Far Away.'),
('Dune: Part Three', 'Movie', 2026, '2h 55m', 'PG-13', 9.1, '210K', 'https://picsum.photos/seed/dune3/300/450', 'https://picsum.photos/seed/dune3-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Sci-Fi', 'Adventure', 'Drama'], 'English', 'in-theaters', '$45M', '$890M', 'Denis Villeneuve concludes his Dune trilogy with Paul Atreides facing the consequences of the jihad unleashed in his name.'),
('Avengers: Doomsday', 'Movie', 2026, '2h 38m', 'PG-13', 8.7, '340K', 'https://picsum.photos/seed/doomsday/300/450', 'https://picsum.photos/seed/doomsday-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Adventure', 'Superhero'], 'English', 'in-theaters', '$112M', '$1.8B', 'Robert Downey Jr. returns as Doctor Doom. The Multiverse Saga reaches its cataclysmic climax in the biggest Marvel event yet.'),
('Deadpool & Wolverine 2', 'Movie', 2026, '2h 10m', 'R', 8.3, '195K', 'https://picsum.photos/seed/deadpool2/300/450', 'https://picsum.photos/seed/deadpool2-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Comedy', 'Superhero'], 'English', 'in-theaters', '$52M', '$1.2B', 'The Merc with a Mouth and the grumpiest X-Man reunite for another chaotic, fourth-wall-breaking, R-rated adventure through the multiverse.');
