('The Mandalorian & Grogu', 'Movie', 2026, '2h 15m', 'PG-13', 8.5, '62K', 'https://picsum.photos/seed/mando/300/450', 'https://picsum.photos/seed/mando-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Sci-Fi', 'Adventure', 'Action'], 'English', 'coming-soon', 'NOV 22', 280, 195, true, 'Din Djarin and Grogu return in their first feature film. A new threat emerges from the Outer Rim that could change the galaxy forever.'),
('Frozen 3', 'Movie', 2026, '1h 50m', 'PG', 7.5, '45K', 'https://picsum.photos/seed/frozen3/300/450', 'https://picsum.photos/seed/frozen3-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Animation', 'Musical', 'Family'], 'English', 'coming-soon', 'DEC 20', 190, 140, true, 'Elsa discovers the true origin of her powers in a journey beyond Arendelle that reveals ancient magic and a long-lost kingdom.'),
('Star Wars: New Jedi Order', 'Movie', 2027, '2h 30m', 'PG-13', 8.8, '78K', 'https://picsum.photos/seed/starwars-njo/300/450', 'https://picsum.photos/seed/starwars-njo-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Sci-Fi', 'Adventure', 'Action'], 'English', 'coming-soon', 'MAY 22', 420, 310, true, 'Rey rebuilds the Jedi Order 15 years after The Rise of Skywalker. A new darkness stirs in the Unknown Regions.');
INSERT INTO movies (title, type, year, duration, age_rating, star_rating, vote_count, poster_url, backdrop_url, trailer_url, genres, language, category, streaming_on, release_date, description) VALUES
('Superman', 'Movie', 2025, '2h 30m', 'PG-13', 8.4, '180K', 'https://picsum.photos/seed/superman25/300/450', 'https://picsum.photos/seed/superman25-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Adventure', 'Superhero'], 'English', 'streaming-soon', ARRAY['Max'], 'AUG 15', 'James Gunn''s fresh take on the Man of Steel. David Corenswet soars as Clark Kent in a hopeful, heartfelt reboot that reminds us why we need Superman.'),
('Fantastic Four: First Steps', 'Movie', 2025, '2h 5m', 'PG-13', 8.0, '145K', 'https://picsum.photos/seed/fantastic4/300/450', 'https://picsum.photos/seed/fantastic4-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Adventure', 'Superhero'], 'English', 'streaming-soon', ARRAY['Disney+'], 'AUG 22', 'Marvel''s First Family finally gets the MCU treatment they deserve. Pedro Pascal leads as Reed Richards in a retro-futuristic 1960s adventure.'),
('Jurassic World: Rebirth', 'Movie', 2025, '2h 15m', 'PG-13', 7.6, '132K', 'https://picsum.photos/seed/jurassic-rebirth/300/450', 'https://picsum.photos/seed/jurassic-rebirth-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Adventure', 'Sci-Fi'], 'English', 'streaming-soon', ARRAY['Peacock'], 'SEP 1', 'Scarlett Johansson leads the dinosaur franchise revival. A daring expedition to a remote island reveals dinosaurs thriving in ways no one imagined.'),
('Mission: Impossible – The Final Reckoning', 'Movie', 2025, '2h 45m', 'PG-13', 8.6, '210K', 'https://picsum.photos/seed/mi-final/300/450', 'https://picsum.photos/seed/mi-final-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Action', 'Thriller', 'Adventure'], 'English', 'streaming-soon', ARRAY['Paramount+'], 'SEP 8', 'Tom Cruise''s final mission as Ethan Hunt. The stakes have never been higher as the IMF faces an enemy that knows every move they''ll make.'),
('Wicked: Part Two', 'Movie', 2025, '2h 30m', 'PG', 8.3, '165K', 'https://picsum.photos/seed/wicked2/300/450', 'https://picsum.photos/seed/wicked2-bg/1200/600', 'https://www.youtube.com/embed/dQw4w9WgXcQ', ARRAY['Musical', 'Fantasy', 'Drama'], 'English', 'streaming-soon', ARRAY['Prime Video'], 'SEP 15', 'The billion-dollar musical phenomenon concludes. Elphaba and Glinda''s paths diverge as Oz descends into darkness, leading to the fateful melting we all know.');
